using System;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using LWS.TruckSports.Editor;
namespace LWS.TruckNinjaWarrior.Editor
{
 public static class NinjaPresentation
 {
  public static void CorrectSeesawClearances(){EditorSceneManager.OpenScene(NinjaAuthoring.Scene);var match=UnityEngine.Object.FindAnyObjectByType<NinjaMatch>();foreach(var t in UnityEngine.Object.FindObjectsByType<Transform>(FindObjectsInactive.Include)){if(t.name!="Broad safe checkpoint landing")continue;float centre=0,length=0;if(Mathf.Abs(t.position.z-368)<.1f||Mathf.Abs(t.position.z-362.5f)<.1f){centre=362.5f;length=19;}else if(Mathf.Abs(t.position.z-449)<.1f||Mathf.Abs(t.position.z-452)<.1f){centre=452;length=24;}else continue;var p=t.position;p.z=centre;t.position=p;foreach(var box in t.GetComponentsInChildren<BoxCollider>()){var scale=box.transform.localScale;scale.z=length;box.transform.localScale=scale;}}EditorSceneManager.SaveScene(match.gameObject.scene);AssetDatabase.SaveAssets();}
  public static void CorrectArticulatedContacts()
  {
   EditorSceneManager.OpenScene(NinjaAuthoring.Scene);var match=UnityEngine.Object.FindAnyObjectByType<NinjaMatch>();var start=GameObject.Find("Grounded starting showcase platform");foreach(var box in start.GetComponentsInChildren<BoxCollider>()){var scale=box.transform.localScale;scale.z=78;box.transform.localScale=scale;}
   foreach(var body in match.course.movingBodies){var joint=body.GetComponent<ConfigurableJoint>();if(joint==null||!body.name.Contains("step")&&!body.name.Contains("seesaw")||joint.connectedBody!=null)continue;var anchor=joint.connectedAnchor;var parts=Array.FindAll(UnityEngine.Object.FindObjectsByType<Transform>(FindObjectsInactive.Include),t=>(t.name=="Grounded truss concrete footing"||t.name=="Actual obstacle structural support")&&Mathf.Abs(t.position.x-anchor.x)<.01f&&Mathf.Abs(t.position.z-anchor.z)<.01f);if(parts.Length!=2)throw new InvalidOperationException("Expected both existing support meshes for "+body.name);var root=new GameObject("Collision-isolated structural hinge support "+body.name);root.transform.position=anchor;foreach(var part in parts)part.SetParent(root.transform,true);var support=root.AddComponent<Rigidbody>();support.isKinematic=true;support.useGravity=false;joint.connectedBody=support;joint.autoConfigureConnectedAnchor=false;joint.connectedAnchor=Vector3.zero;joint.enableCollision=false;Debug.Log("NINJA_ARTICULATED_SUPPORT "+body.name+" anchor="+anchor+" support parts="+parts.Length);}
   EditorSceneManager.SaveScene(match.gameObject.scene);AssetDatabase.SaveAssets();
  }
  public static void BindWarpedWall(){EditorSceneManager.OpenScene(NinjaAuthoring.Scene);var match=UnityEngine.Object.FindAnyObjectByType<NinjaMatch>();match.course.warpedWall=GameObject.Find("Genuine curved warped-wall collision surface").GetComponent<Collider>();EditorSceneManager.SaveScene(match.gameObject.scene);AssetDatabase.SaveAssets();}
  public static void RobustStepLanding(){EditorSceneManager.OpenScene(NinjaAuthoring.Scene);var match=UnityEngine.Object.FindAnyObjectByType<NinjaMatch>();foreach(var t in UnityEngine.Object.FindObjectsByType<Transform>(FindObjectsInactive.Include))if(t.name=="Broad safe checkpoint landing"&&Mathf.Abs(t.position.z-(match.course.checkpoints[0].z+3))<.1f){foreach(var shape in t.GetComponentsInChildren<BoxCollider>()){var scale=shape.transform.localScale;scale.z=42;shape.transform.localScale=scale;}foreach(var rim in t.GetComponentsInChildren<Transform>())if(rim.name=="Readable obstacle colored rim"){var scale=rim.localScale;scale.z=42;rim.localScale=scale;}}EditorSceneManager.SaveScene(match.gameObject.scene);AssetDatabase.SaveAssets();}
  public static void BindFinishAudio(){EditorSceneManager.OpenScene(NinjaAuthoring.Scene);var match=UnityEngine.Object.FindAnyObjectByType<NinjaMatch>();var clip=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/TruckFishing/Audio/Fishing result chime.wav");if(clip==null)throw new InvalidOperationException("Existing original Sports result chime required");match.feedback.clips[6]=clip;SportsRallyAuthoring.TuneCamera(match.broadcast);EditorSceneManager.SaveScene(match.gameObject.scene);AssetDatabase.SaveAssets();}
  public static void AlignFinale(){EditorSceneManager.OpenScene(NinjaAuthoring.Scene);var landing=GameObject.Find("Elevated full-truck victory landing");if(landing==null)throw new InvalidOperationException("Saved victory landing required");var p=landing.transform.position;p.z=658.6f;landing.transform.position=p;var support=landing.GetComponent<Rigidbody>();if(support==null)support=landing.AddComponent<Rigidbody>();support.isKinematic=true;UnityEngine.Object.FindAnyObjectByType<NinjaMatch>().course.finaleLanding=support;EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());AssetDatabase.SaveAssets();}
  public static void TuneLogs(){EditorSceneManager.OpenScene(NinjaAuthoring.Scene);foreach(var rotor in UnityEngine.Object.FindObjectsByType<NinjaRotator>(FindObjectsInactive.Include))if(rotor.name.StartsWith("Enormous rotating traction log")){bool first=rotor.name.EndsWith("0");var p=rotor.body.position;p.y=2;rotor.body.position=p;rotor.transform.position=p;rotor.transform.localScale=new Vector3(20,17,20);rotor.degreesPerSecond=first?8:-9;}EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());AssetDatabase.SaveAssets();}
  public static void Finish()
  {
   EditorSceneManager.OpenScene(NinjaAuthoring.Scene);if(GameObject.Find("Finished Ninja stadium fixtures and obstacle signage")!=null)throw new InvalidOperationException("Preserve existing stadium presentation edits.");var root=new GameObject("Finished Ninja stadium fixtures and obstacle signage").transform;var steel=AssetDatabase.LoadAssetAtPath<Material>("Assets/TruckNinjaWarrior/Materials/Brushed game-show structural steel.mat");var teal=AssetDatabase.LoadAssetAtPath<Material>("Assets/TruckNinjaWarrior/Materials/Scuffed electric teal obstacle enamel.mat");var coral=AssetDatabase.LoadAssetAtPath<Material>("Assets/TruckNinjaWarrior/Materials/Arcade coral structural trim.mat");var artwork=AssetDatabase.LoadAssetAtPath<Material>("Assets/TruckNinjaWarrior/Materials/Original grungy Ninja stadium artwork.mat");var lens=SportsEventAuthoring.Mat(NinjaAuthoring.Folder,"Bright visible floodlight lenses",new Color(1,.9f,.7f));lens.EnableKeyword("_EMISSION");lens.SetColor("_EmissionColor",new Color(1,.85f,.65f)*3);
   string[] names={"01 · TILT TRIPLE","02 · ROLLING LOGS","03 · WRECKING ROW","04 · TIP THE BRIDGE","05 · SPIN TO WIN","06 · RING THE BELL"};float[] z={0,140,270,380,460,610};for(int i=0;i<6;i++){var p=new Vector3(31,21,z[i]);SportsEventAuthoring.Box("Physical obstacle-number sign support",new Vector3(31,10.5f,z[i]+.5f),new Vector3(.5f,21,.5f),steel,null,root);SportsEventAuthoring.Box("Branded obstacle identification panel",p+Vector3.forward*.2f,new Vector3(27,5,.25f),i%2==0?coral:teal,null,root);var label=SportsEventAuthoring.Label("Diegetic game-show obstacle identity",names[i],p,.115f,Color.white);label.transform.SetParent(root,true);}
   for(int i=0;i<12;i++)foreach(int side in new[]{-1,1}){var p=new Vector3(side*65,35,-40+i*65);var fixture=new GameObject("Complete physical stadium floodlight fixture").transform;fixture.SetParent(root,true);fixture.SetPositionAndRotation(p,Quaternion.Euler(65,side>0?-90:90,0));SportsEventAuthoring.Box("Floodlight steel housing",Vector3.zero,new Vector3(3.4f,1.8f,.7f),steel,null,fixture);for(int a=-1;a<=1;a++)for(int b=0;b<2;b++)SportsEventAuthoring.Box("Visible stadium lamp reflector",new Vector3(a, b==0?-.45f:.45f,-.37f),new Vector3(.8f,.65f,.08f),lens,null,fixture);}
   if(artwork==null)throw new InvalidOperationException("Original imported Ninja logo material required.");for(int i=0;i<8;i++)foreach(int side in new[]{-1,1}){var sign=GameObject.CreatePrimitive(PrimitiveType.Quad);sign.name="Original Ninja arena sponsor banner";UnityEngine.Object.DestroyImmediate(sign.GetComponent<Collider>());sign.transform.SetParent(root,true);sign.transform.SetPositionAndRotation(new Vector3(side*96,22,-30+i*95),Quaternion.Euler(0,side<0?-90:90,0));sign.transform.localScale=new Vector3(40,24,1);sign.GetComponent<Renderer>().sharedMaterial=artwork;foreach(int end in new[]{-1,1})SportsEventAuthoring.Box("Grounded stadium banner upright",new Vector3(side*97,18,-30+i*95+end*21),new Vector3(.5f,36,.5f),steel,null,root);}
   EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());AssetDatabase.SaveAssets();
  }
 }
}
